#define t iTime/11.

#define rot(a) mat2(cos(a+vec4(0,11,33,0)))
void mainImage0( out vec4 O, vec2 u )
{
    vec2  R =  iResolution.xy, m=iMouse.xy, z,
          U = ( u+u - R )/ R.y *  vec2(.002) ,
          M = iMouse.z>0.? ( m+m - R )/ R.y : vec2(0);
    float i = -2.;

    z = U*rot(-t) - vec2(.444153,.693785) ;
    float an=2.65;
    vec2 jp = .495*vec2(cos(an),sin(an)) - M/50.; //Julia Set param

    for ( O *= 0. ; i++ < 110.; ) //  ||iterates|| stays less < 1
        z = 
            //just taking abs of regular z^c
            abs(mat2(z,-z.y,z.x) * z)        
            + jp ,

        //count times orbit goes through each quadrant
        //golfed from a bunch of if statements by fabriceneyret2          
        O[ int(z.x<0.)*2 + int(z.y<0.) ]++;          

    O = cos( O.yzxw * vec4(0,30.5,18,0) / i  );  //change colors here

    O*=O;
}

//FabriceNeyret2 antialiasing trick
void mainImage(out vec4 O, vec2 U) {
    mainImage0(O,U);
    if ( fwidth(length(O)) > .001 ) {  // difference threshold between neighbor pixels
        vec4 o;
        for (int k=0; k < 9; k+= k==3?2:1 )
          { mainImage0(o,U+vec2(k%3-1,k/3-1)/3.); O += o; }
        O /= 9.;
        //O.b++; // uncomment to see where the oversampling occurs
    }
}
